 	mapping->nrpages -= nr;

 	for (i = 0; i < nr; i++) {
 		node = radix_tree_replace_clear_tags(&mapping->page_tree,
 				page->index + i, shadow);
 		if (!node) {
 			VM_BUG_ON_PAGE(nr != 1, page);
 			return;
 		}

 		workingset_node_pages_dec(node);
 		if (shadow)
 			workingset_node_shadows_inc(node);
 		else
